    Object[] oIntArr2 = new Object[NUM_ROWS];
    for (int rowId = 0; rowId < NUM_ROWS; rowId++) {
        builder.startRow();
        int size1 = r.nextInt(15);
        int size2 = r.nextInt(15);
        int[] arr1 = new int[size1];
        int[] arr2 = new int[size2];
        for (int j = 0; j < size1; j++) {
