            data[i] = value;
            writer.setInt(i, 0, data[i]);
            int offsetValue = value + offset;
            for (int bitPos = requiredBits - 1; bitPos >= 0; bitPos--) {
                if ((offsetValue & (1 << bitPos)) != 0) {
                    set.setBit(i * requiredBits + (requiredBits - bitPos - 1));
                }
            }
        }
