@Test
void testDataRefresh() throws Exception {
    manager = new StarTreeManagerImpl();
    manager.restore(rootDir, collection);
    starTrees = manager.getStarTrees(collection);
    Assert.assertEquals(starTrees.size(), 0);
    // create data directory
    File dataDir1 = new File(collectionDir, "data_1");
    StarTreePersistanceUtil.saveTree(starTree, dataDir1.getPath());
    FileUtils.moveFile(new File(dataDir1, collection + "-tree.bin"), new File(dataDir1, StarTreeConstants.TREE_FILE_NAME));
    properties.store(new FileOutputStream(new File(dataDir1, StarTreeConstants.METADATA_FILE_NAME)), "properties file");
    pollForStarTreesAddition(dataDir1);
    Assert.assertEquals("starTrees not updated", starTrees.size(), 1);
    Assert.assertTrue(starTrees.containsKey(dataDir1));
    // delete segment
    FileUtils.deleteDirectory(dataDir1);
    // create new data directory
    File dataDir2 = new File(collectionDir, "data_2");
    StarTreePersistanceUtil.saveTree(starTree, dataDir2.getPath());
    FileUtils.moveFile(new File(dataDir2, collection + "-tree.bin"), new File(dataDir2, StarTreeConstants.TREE_FILE_NAME));
    properties.store(new FileOutputStream(new File(dataDir2, StarTreeConstants.METADATA_FILE_NAME)), "properties file");
    pollForStarTreesAddition(dataDir2);
    Assert.assertEquals(starTrees.size(), 1);
    Assert.assertFalse("starTrees did not delete old tree", starTrees.containsKey(dataDir1));
    Assert.assertTrue(starTrees.containsKey(dataDir2));
    FileUtils.deleteDirectory(dataDir1);
}

@Test
public void testInducedSplit() throws Exception {
    StarTreeNode root = createRoot();
    root.init(config, recordStoreFactory);
    for (int i = 0; i < 100; i++) {
        MetricTimeSeries ts = new MetricTimeSeries(metricSchema);
        ts.set(0, "M", 1);
        StarTreeRecordImpl.Builder b = new StarTreeRecordImpl.Builder().setDimensionKey(getDimensionKey("A" + (i % 4), "B" + (i % 8), "C" + (i % 16))).setMetricTimeSeries(ts);
        root.getRecordStore().update(b.build(config));
        StringBuilder sb = new StringBuilder();
        sb.append("B").append(i % 8).append("C").append(i % 16);
    }
    MetricTimeSeries ts = new MetricTimeSeries(metricSchema);
    ts.set(0, "M", 0);
    // Add an "other" value (this should not have explict, but should be in other node)
    StarTreeRecord other = new StarTreeRecordImpl.Builder().setDimensionKey(getDimensionKey(StarTreeConstants.OTHER, StarTreeConstants.OTHER, StarTreeConstants.OTHER)).setMetricTimeSeries(ts).build(config);
    root.getRecordStore().update(other);
    // Split on A (should have 4 children: A0, A1, A2, A3)
    root.split("A");
    Assert.assertEquals(root.getChildren().size(), 4);
    Assert.assertNotNull(root.getOtherNode());
    Assert.assertNotNull(root.getStarNode());
    Assert.assertEquals(root.getChildDimensionName(), "A");
    // Check children
    Set<String> childDimensionValues = new HashSet<String>();
    for (StarTreeNode child : root.getChildren()) {
        Assert.assertEquals(child.getDimensionName(), "A");
        Assert.assertTrue(child.isLeaf());
        childDimensionValues.add(child.getDimensionValue());
    }
    Set<String> expectedValues = new HashSet<String>(Arrays.asList("A0", "A1", "A2", "A3"));
    Assert.assertEquals(childDimensionValues, expectedValues);
    // Check children by explicitly getting
    for (int i = 0; i < 4; i++) {
        Assert.assertNotNull(root.getChild("A" + i));
    }
    // Check invalid child
    Assert.assertNull(root.getChild("A4"));
}

