    { UUID.randomUUID(), createIndexMetadata("2015-01-01TZ", "2015-01-02TZ", "2015-01-01TZ", "2015-01-02TZ", "DAILY") }, // use
    { UUID.randomUUID(), createIndexMetadata("2015-01-02TZ", "2015-01-03TZ", "2015-01-02TZ", "2015-01-03TZ", "DAILY") }, // use
